from pathlib import Path
from evidence_paths import EVIDENCE_ROOT, FINAL_DIR, APPROVALS, load_source_json
import base64
import hashlib
import html
import json
import mimetypes

ROOT = EVIDENCE_ROOT
WORK = Path(__file__).resolve().parent
OUT = FINAL_DIR / '열교환기 백데이터.html'
data = load_source_json(APPROVALS)
doc = next(d for d in data['documents'] if d['docId'] == '334757')
originals = [Path(doc['bodyPdfPath'])] + sorted(Path(doc['attachmentDir']).iterdir())
files = []
for i, p in enumerate(originals):
    if not p.is_file():
        continue
    b = p.read_bytes()
    files.append({'id':f'f{i}', 'name':p.name, 'size':len(b), 'mime':mimetypes.guess_type(p.name)[0] or 'application/octet-stream', 'sha256':hashlib.sha256(b).hexdigest(), 'base64':base64.b64encode(b).decode()})
assert len(files) == 7

def image_data(name):
    p = WORK / name
    mime = mimetypes.guess_type(p.name)[0] or 'image/png'
    return f'data:{mime};base64,' + base64.b64encode(p.read_bytes()).decode()

